[{"order":1,"type":"heading","text":"PHP Arrays: A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"Arrays in PHP are ordered maps. A map is a type that associates values to keys. This tutorial covers indexed, associative, and multidimensional arrays, along with essential array functions."},{"order":3,"type":"subheading","text":"Indexed Arrays"},{"order":4,"type":"paragraph","text":"Indexed arrays are arrays with numeric keys. These keys start at 0 by default and increment automatically."},{"order":5,"type":"code","text":"// Creating an indexed array
$colors = array("Red", "Green", "Blue");

// Accessing elements
echo $colors[0]; // Output: Red
echo $colors[1]; // Output: Green
echo $colors[2]; // Output: Blue

// Determining array length
$length = count($colors);
echo "\nThe array has " . $length . " elements."; // Output: The array has 3 elements."},{"order":6,"type":"subheading","text":"Associative Arrays"},{"order":7,"type":"paragraph","text":"Associative arrays use named keys that you assign. This allows you to create more descriptive and readable data structures."},{"order":8,"type":"code","text":"// Creating an associative array
$age = array("Peter" => "35", "Ben" => "37", "Joe" => "43");

// Accessing elements
echo "Peter is " . $age['Peter'] . " years old.\n"; // Output: Peter is 35 years old.

// Iterating through an associative array
foreach($age as $name => $ageValue) {
  echo $name . " is " . $ageValue . " years old.\n";
}"},{"order":9,"type":"subheading","text":"Multidimensional Arrays"},{"order":10,"type":"paragraph","text":"Multidimensional arrays are arrays containing one or more other arrays. They are useful for representing data with multiple dimensions."},{"order":11,"type":"code","text":"// Creating a multidimensional array
$cars = array(
  array("Volvo", 22, 18),
  array("BMW", 15, 13),
  array("Saab", 5, 2),
  array("Land Rover", 17, 15)
);

// Accessing elements
echo $cars[0][0].": In stock: ".$cars[0][1].", sold: ".$cars[0][2].".\n"; // Output: Volvo: In stock: 22, sold: 18.

//Iterating through a multidimensional array
for ($row = 0; $row < count($cars); $row++) {
  echo "<p><b>Row number $row</b></p>";
  echo "<ul>";
  for ($col = 0; $col < count($cars[$row]); $col++) {
    echo "<li>".$cars[$row][$col]."</li>";
  }
  echo "</ul>";
}"},{"order":12,"type":"subheading","text":"Array Functions"},{"order":13,"type":"paragraph","text":"PHP provides a rich set of functions for manipulating arrays. Here are some commonly used ones:"},{"order":14,"type":"bullet_point","text":"count(): Returns the number of elements in an array."},{"order":15,"type":"code","text":"$myArray = array(1, 2, 3, 4, 5);
echo count($myArray); // Output: 5"},{"order":16,"type":"bullet_point","text":"array_push(): Adds one or more elements to the end of an array."},{"order":17,"type":"code","text":"$myArray = array("apple", "banana");
array_push($myArray, "cherry", "date");
print_r($myArray); // Output: Array ( [0] => apple [1] => banana [2] => cherry [3] => date )"},{"order":18,"type":"bullet_point","text":"array_pop(): Removes the last element from an array."},{"order":19,"type":"code","text":"$myArray = array("apple", "banana", "cherry");
array_pop($myArray);
print_r($myArray); // Output: Array ( [0] => apple [1] => banana )"},{"order":20,"type":"bullet_point","text":"array_shift(): Removes the first element from an array."},{"order":21,"type":"code","text":"$myArray = array("apple", "banana", "cherry");
array_shift($myArray);
print_r($myArray); // Output: Array ( [0] => banana [1] => cherry )"},{"order":22,"type":"bullet_point","text":"array_unshift(): Adds one or more elements to the beginning of an array."},{"order":23,"type":"code","text":"$myArray = array("banana", "cherry");
array_unshift($myArray, "apple");
print_r($myArray); // Output: Array ( [0] => apple [1] => banana [2] => cherry )"},{"order":24,"type":"bullet_point","text":"array_merge(): Merges one or more arrays into one array."},{"order":25,"type":"code","text":"$array1 = array("a" => "apple", "b" => "banana");
$array2 = array("c" => "cherry", "d" => "date");
$mergedArray = array_merge($array1, $array2);
print_r($mergedArray); // Output: Array ( [a] => apple [b] => banana [c] => cherry [d] => date )"},{"order":26,"type":"bullet_point","text":"array_keys(): Returns all the keys of an array."},{"order":27,"type":"code","text":"$myArray = array("a" => "apple", "b" => "banana", "c" => "cherry");
$keys = array_keys($myArray);
print_r($keys); // Output: Array ( [0] => a [1] => b [2] => c )"},{"order":28,"type":"bullet_point","text":"array_values(): Returns all the values of an array."},{"order":29,"type":"code","text":"$myArray = array("a" => "apple", "b" => "banana", "c" => "cherry");
$values = array_values($myArray);
print_r($values); // Output: Array ( [0] => apple [1] => banana [2] => cherry )"},{"order":30,"type":"bullet_point","text":"in_array(): Checks if a value exists in an array."},{"order":31,"type":"code","text":"$myArray = array("apple", "banana", "cherry");
if (in_array("banana", $myArray)) {
  echo "Banana is in the array.\n"; // Output: Banana is in the array.
}"},{"order":32,"type":"bullet_point","text":"array_search(): Searches an array for a given value and returns the corresponding key if successful."},{"order":33,"type":"code","text":"$myArray = array("a" => "apple", "b" => "banana", "c" => "cherry");
$key = array_search("banana", $myArray);
echo $key; // Output: b"},{"order":34,"type":"bullet_point","text":"sort(): Sorts an indexed array in ascending order."},{"order":35,"type":"code","text":"$myArray = array("cherry", "banana", "apple");
sort($myArray);
print_r($myArray); // Output: Array ( [0] => apple [1] => banana [2] => cherry )"},{"order":36,"type":"bullet_point","text":"asort(): Sorts an associative array in ascending order, according to the value."},{"order":37,"type":"code","text":"$myArray = array("a" => "cherry", "b" => "banana", "c" => "apple");
asort($myArray);
print_r($myArray); // Output: Array ( [c] => apple [b] => banana [a] => cherry )"},{"order":38,"type":"bullet_point","text":"ksort(): Sorts an associative array in ascending order, according to the key."},{"order":39,"type":"code","text":"$myArray = array("a" => "cherry", "c" => "banana", "b" => "apple");
ksort($myArray);
print_r($myArray); // Output: Array ( [a] => cherry [b] => apple [c] => banana )"},{"order":40,"type":"paragraph","text":"These are just a few of the many array functions available in PHP. Refer to the PHP documentation for a complete list and detailed explanations."}]
